S=()=>{
	data=source.getVariable()
	if(data==""){
		source.setVariable("文本")
	java.longToast("设置文本模式📖")
}else if(data=="文本"){
	source.setVariable("文件")
java.longToast("设置文件模式📥")
}else{	
	source.setVariable("文本")
java.longToast("设置文本模式📖")}
	}
G=()=>{
	data = source.getVariable()==""?source.setVariable("文本"):source.getVariable();
	m = data=="文件"?"📥":"📖"
	java.longToast("当前"+data+"模式"+m);
	}
H=()=>{
	java.longToast(`
		默认模式为小说
		点击切换为文件
		`);
	}

