(() =>{
let host = source.key+"/e/search/";
let url = host+"indexsearch.php";
let body="keyboard="+String(java.encodeURI(key,"gb2312"))+"&show=title&classid=0";
if (page==1) {
	let l = java.post(url,body,{"Origin":source.key,"Referer":source.key,"content-type":"application/x-www-form-urlencoded"}).headers("location")[0] || "";
	source.put("l",l)
	return host+l+","+JSON.stringify({"charset": "gb2312"});
} else {
	let 	g = source.get("l");
	let rel = String(g).replace(/\?/,`index.php?page=${page-1}&`);
	return `${host}${rel},${JSON.stringify({"charset": "gb2312"})}`
	}
})()

