;[
		["男",[["玄幻","lejRej"],["武侠","nel5aK"],["都市","mbk5ez"],["仙侠","vbmOeY"],["军事","penRe7"],["历史","xbojag"],["游戏","mep2bM"],["科幻","zbq2dp"],["轻小说","YerEdO"]]],
		["女",[["现代言情","9avmeG"],["古代言情","DdwRb1"],["幻想言情","7ax9by"],["青春校园","Pdy7aQ"],["唯美纯爱","kazYeJ"],["同人衍生","9aAOdv"]]]
].map(([title,list],channel)=>{
		channel++;
