						i = "rank?type="+i+"&";
					}
				else{
						i = i<8?"mep2bM?":"YerEdO?";
					}
				push(title,$$(i,channel,1),0.25);
			});
		push("༺ˇ»`ʚ 分类 ɞ´«ˇ༻",null,1);
		list.map([title,B]=>{
				push("༺ "+title+" ༻",$$(1,B,0),1);
				["热度","更新","评分","新书"].map((title,A)=>{
						A++;
						["["+title+"]","连载","完结"].map((title,C)=>{
								C=C?"&isComplete="+(C-1):"";
								push(title,$$(A,B+C,0),0.25);
							});
					});
			});
	}); 
